config.jsonSchemaText:
{
  "title": "ExtractedOrder",
  "description": "Structured order data extracted from parsed documents.",
  "type": "object",
  "properties": {
    "supplier_name": {
      "title": "Supplier Name",
      "type": "string",
      "default": ""
    },
    "supplier_code": {
      "title": "Supplier Code",
      "type": "string",
      "default": ""
    },
    "supplier_address": {
      "title": "Supplier Address",
      "type": "string",
      "default": ""
    },
    "supplier_contacts": {
      "title": "Supplier Contacts",
      "type": "array",
      "items": {
        "title": "ContactEntry",
        "type": "object",
        "properties": {
          "type": {
            "title": "Type",
            "type": "string"
          },
          "value": {
            "title": "Value",
            "type": "string"
          }
        },
        "required": [
          "type",
          "value"
        ]
      }
    },
    "buyer_name": {
      "title": "Buyer Name",
      "type": "string",
      "default": ""
    },
    "buyer_code": {
      "title": "Buyer Code",
      "type": "string",
      "default": ""
    },
    "buyer_address": {
      "title": "Buyer Address",
      "type": "string",
      "default": ""
    },
    "delivery_address": {
      "title": "Delivery Address",
      "type": "string",
      "default": ""
    },
    "buyer_contacts": {
      "title": "Buyer Contacts",
      "type": "array",
      "items": {
        "title": "ContactEntry",
        "type": "object",
        "properties": {
          "type": {
            "title": "Type",
            "type": "string"
          },
          "value": {
            "title": "Value",
            "type": "string"
          }
        },
        "required": [
          "type",
          "value"
        ]
      }
    },
    "order_id": {
      "title": "Order Id",
      "type": "string"
    },
    "order_date": {
      "title": "Order Date",
      "type": "string",
      "default": ""
    },
    "currency": {
      "title": "Currency",
      "type": "string",
      "default": ""
    },
    "order_total": {
      "title": "Order Total",
      "type": "number",
      "default": 0
    },
    "line_items": {
      "title": "Line Items",
      "type": "array",
      "items": {
        "title": "OrderLineItem",
        "type": "object",
        "properties": {
          "line_number": {
            "title": "Line Number",
            "type": "integer"
          },
          "sku": {
            "title": "Sku",
            "type": "string"
          },
          "product_description": {
            "title": "Product Description",
            "type": "string"
          },
          "quantity": {
            "title": "Quantity",
            "type": "integer"
          },
          "unit_of_measure": {
            "title": "Unit Of Measure",
            "type": "string"
          },
          "unit_price": {
            "title": "Unit Price",
            "type": "number"
          },
          "total_price": {
            "title": "Total Price",
            "type": "number"
          }
        },
        "required": [
          "line_number",
          "sku",
          "product_description",
          "quantity",
          "unit_of_measure",
          "unit_price",
          "total_price"
        ]
      }
    },
    "additional_info": {
      "title": "Additional Info",
      "type": "array",
      "items": {
        "title": "AdditionalInfoEntry",
        "type": "object",
        "properties": {
          "key": {
            "title": "Key",
            "type": "string"
          },
          "value": {
            "title": "Value",
            "type": "string"
          }
        },
        "required": [
          "key",
          "value"
        ]
      }
    },
    "extraction_confidence": {
      "title": "Extraction Confidence",
      "type": "number",
      "default": 1
    }
  }
}
